drop extension if exists "pg_net";


  create table "public"."vizzion_activity_log" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid,
    "actor_name" text not null default 'Integrante'::text,
    "action" text not null,
    "entity_type" text not null default 'general'::text,
    "entity_id" text,
    "details" jsonb not null default '{}'::jsonb,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."vizzion_activity_log" enable row level security;


  create table "public"."vizzion_products" (
    "id" text not null,
    "title" text not null default ''::text,
    "category" text not null default ''::text,
    "product_data" jsonb not null default '{}'::jsonb,
    "updated_at" timestamp with time zone not null default now()
      );


alter table "public"."vizzion_products" enable row level security;


  create table "public"."vizzion_profiles" (
    "user_id" uuid not null,
    "display_name" text not null default ''::text,
    "role" text not null default 'member'::text,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."vizzion_profiles" enable row level security;


  create table "public"."vizzion_state" (
    "id" text not null default 'main'::text,
    "state" jsonb not null default '{}'::jsonb,
    "updated_at" timestamp with time zone not null default now()
      );


alter table "public"."vizzion_state" enable row level security;

CREATE INDEX idx_vizzion_activity_created_at ON public.vizzion_activity_log USING btree (created_at DESC);

CREATE INDEX idx_vizzion_activity_user_id ON public.vizzion_activity_log USING btree (user_id);

CREATE INDEX idx_vizzion_products_category ON public.vizzion_products USING btree (category);

CREATE INDEX idx_vizzion_products_title ON public.vizzion_products USING btree (title);

CREATE UNIQUE INDEX vizzion_activity_pkey ON public.vizzion_activity_log USING btree (id);

CREATE UNIQUE INDEX vizzion_products_pkey ON public.vizzion_products USING btree (id);

CREATE UNIQUE INDEX vizzion_profiles_pkey ON public.vizzion_profiles USING btree (user_id);

CREATE UNIQUE INDEX vizzion_state_pkey ON public.vizzion_state USING btree (id);

alter table "public"."vizzion_activity_log" add constraint "vizzion_activity_pkey" PRIMARY KEY using index "vizzion_activity_pkey";

alter table "public"."vizzion_products" add constraint "vizzion_products_pkey" PRIMARY KEY using index "vizzion_products_pkey";

alter table "public"."vizzion_profiles" add constraint "vizzion_profiles_pkey" PRIMARY KEY using index "vizzion_profiles_pkey";

alter table "public"."vizzion_state" add constraint "vizzion_state_pkey" PRIMARY KEY using index "vizzion_state_pkey";

alter table "public"."vizzion_activity_log" add constraint "vizzion_activity_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL not valid;

alter table "public"."vizzion_activity_log" validate constraint "vizzion_activity_user_id_fkey";

alter table "public"."vizzion_profiles" add constraint "vizzion_profiles_role_check" CHECK ((role = ANY (ARRAY['admin'::text, 'member'::text]))) not valid;

alter table "public"."vizzion_profiles" validate constraint "vizzion_profiles_role_check";

alter table "public"."vizzion_profiles" add constraint "vizzion_profiles_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE not valid;

alter table "public"."vizzion_profiles" validate constraint "vizzion_profiles_user_id_fkey";

alter table "public"."vizzion_state" add constraint "vizzion_state_id_check" CHECK ((id = 'main'::text)) not valid;

alter table "public"."vizzion_state" validate constraint "vizzion_state_id_check";

